//! Rendering what happened, from the record rather than from the model's prose.
//!
//! The report is generated by the host: findings appear with their kind and evidence ids, task
//! results with their real exit statuses and returned artifacts, and the limits of the run are
//! stated in the document rather than left for a reader to discover. `report.md` can be read without
//! the model that produced the investigation being available again.

use crate::execute::{Artifact, TaskResult};
use crate::orchestrator::{Delivery, Outcome, RunReport, Suggestion};
use crate::plan::{Plan, ValidatedPlan};
use aporia_store::Json;
use std::fmt::Write as _;

/// The plan as a person reviews it, and as the report repeats it.
#[must_use]
pub fn render_plan(plan: &Plan) -> String {
    let mut out = String::from("Proposed plan\n");
    out.push_str("Gaps:\n");
    for gap in &plan.gaps {
        let _ = writeln!(
            out,
            "  {} [{}] {}\n    why: {}\n    condition: {}\n    evidence: {}",
            gap.id,
            gap.priority.as_str(),
            gap.title,
            gap.why,
            gap.condition,
            gap.evidence.join(", ")
        );
    }
    out.push_str("Tasks:\n");
    for task in &plan.tasks {
        let _ = writeln!(
            out,
            "  {} {} -- {}\n    question: {}\n    depends on: {}\n    method: {}\n    expected evidence: {}\n    success criteria: {}\n    cost: {}; risk: {}",
            task.id,
            task.tool.as_str(),
            task.title,
            task.question,
            if task.depends_on.is_empty() {
                "none".to_string()
            } else {
                task.depends_on.join(", ")
            },
            task.method,
            task.expected_evidence,
            task.success_criteria,
            task.estimated_cost,
            task.risk
        );
    }
    out
}

/// The human report.
#[must_use]
pub fn render_report(report: &RunReport) -> String {
    let mut out = String::new();
    header(&mut out, report);
    if let Some(failure) = &report.failure {
        let _ = writeln!(out, "\n## Failure\n\n{failure}\n");
    }
    if report.outcome == Outcome::Refused {
        out.push_str("\nThe plan was refused. No task ran.\n");
    }
    if report.outcome == Outcome::BudgetExhausted {
        out.push_str("\nThe budget ran out. This record is deliberately incomplete.\n");
    }
    gaps_section(&mut out, report.plan.as_ref());
    plan_section(&mut out, report);
    results_section(&mut out, report);
    findings_section(&mut out, report);
    delivery_section(&mut out, report);
    suggestions_section(&mut out, &report.suggestions);
    limits_section(&mut out);
    record_section(&mut out, report);
    out
}

fn header(out: &mut String, report: &RunReport) {
    let _ = writeln!(out, "# Investigation {}", report.id);
    let _ = writeln!(out, "\nOutcome: **{}**", report.outcome.as_str());
    let _ = writeln!(out, "\nObjective: {}", report.objective);
    let _ = writeln!(out, "\nSource: {}", report.source.display());
    let _ = writeln!(
        out,
        "Source git HEAD: {}",
        report
            .inspection
            .summary
            .git_head
            .as_deref()
            .unwrap_or("not detected")
    );
    let _ = writeln!(out, "Started: {}", report.started);
    let _ = writeln!(out, "Finished: {}", report.finished);
    let _ = writeln!(out, "\nProvider: {}", report.provider);
    if report.provider.contains("scripted") {
        let _ = writeln!(
            out,
            "\n**The provider was a scripted transcript. No model was consulted for this record.**"
        );
    }
    let _ = writeln!(
        out,
        "\n## What was real\n\n- The source was read, never written. Commands ran in a copy: {} files, {} bytes, {} ignored directories.\n- Tasks executed: {}.\n- Findings recorded: {}.\n- Model turns: {}; tool calls and executions: {}.",
        report.copy.files.len(),
        report.copy.total_bytes,
        report.copy.ignored.len(),
        report.results.len(),
        report.findings.len(),
        report.turns,
        report.calls
    );
}

fn gaps_section(out: &mut String, plan: Option<&Plan>) {
    match plan {
        None => out.push_str("\n## Gaps\n\nNo plan was proposed.\n"),
        Some(plan) => {
            out.push_str("\n## Gaps\n");
            for gap in &plan.gaps {
                let _ = writeln!(
                    out,
                    "\n### {} [{}] {}\n\nWhy: {}\n\nCondition: {}\n\nEvidence: {}\n",
                    gap.id,
                    gap.priority.as_str(),
                    gap.title,
                    gap.why,
                    gap.condition,
                    gap.evidence.join(", ")
                );
            }
        }
    }
}

fn plan_section(out: &mut String, report: &RunReport) {
    out.push_str("\n## Plan and approval\n\n");
    match report.approved {
        Some(true) => out.push_str("The plan was approved.\n"),
        Some(false) => out.push_str("The plan was refused.\n"),
        None => out.push_str("No approval decision was recorded.\n"),
    }
    let Some(plan) = &report.plan else {
        return;
    };
    out.push_str(
        "\n| task | tool | operation | status | exit | duration |\n|---|---|---|---|---|---|\n",
    );
    for task in &plan.tasks {
        let result = report
            .results
            .iter()
            .find(|result| result.task_id == task.id);
        let operation = operation_text(report.validated.as_ref(), &task.id)
            .unwrap_or_else(|| "not run".to_string());
        let status = result.map_or("not run", |result| result.status.as_str());
        let exit = result
            .and_then(|result| result.exit_code)
            .map_or_else(|| "-".to_string(), |code| code.to_string());
        let duration = result.map_or_else(
            || "-".to_string(),
            |result| format!("{} ms", result.duration_ms),
        );
        let _ = writeln!(
            out,
            "| `{}` | {} | {} | {} | {} | {} |",
            task.id,
            task.tool.as_str(),
            operation,
            status,
            exit,
            duration
        );
    }
}

fn results_section(out: &mut String, report: &RunReport) {
    if report.results.is_empty() {
        out.push_str("\n## Executed tasks\n\nNo task ran.\n");
        return;
    }
    out.push_str("\n## Executed tasks\n");
    for result in &report.results {
        out.push_str(&format_result(result));
    }
}

fn format_result(result: &TaskResult) -> String {
    let mut out = format!(
        "\n### {} ({})\n\n- task: `{}`\n- status: {}\n- exit: {}\n- duration: {} ms\n",
        result.id,
        result.tool,
        result.task_id,
        result.status,
        result
            .exit_code
            .map_or_else(|| "none".to_string(), |code| code.to_string()),
        result.duration_ms
    );
    if !result.note.is_empty() {
        let _ = writeln!(out, "- note: {}", result.note);
    }
    for artifact in &result.artifacts {
        let _ = writeln!(
            out,
            "- artifact: {} at `{}` (sha256 {}, {} files)",
            artifact.kind, artifact.path, artifact.sha256, artifact.files
        );
    }
    if !result.stdout.text.is_empty() {
        let _ = writeln!(
            out,
            "\nCaptured stdout ({} bytes, sha256 {}, truncated {}):\n\n```text\n{}\n```",
            result.stdout.bytes, result.stdout.sha256, result.stdout.truncated, result.stdout.text
        );
    }
    if !result.stderr.text.is_empty() {
        let _ = writeln!(
            out,
            "\nCaptured stderr ({} bytes, sha256 {}, truncated {}):\n\n```text\n{}\n```",
            result.stderr.bytes, result.stderr.sha256, result.stderr.truncated, result.stderr.text
        );
    }
    out
}

fn findings_section(out: &mut String, report: &RunReport) {
    out.push_str("\n## Findings\n\n");
    if report.findings.is_empty() {
        out.push_str("No finding was recorded.\n");
        return;
    }
    out.push_str(
        "Kinds are the model's own statements, checked only for evidence that the host recorded.\n\n",
    );
    for (index, finding) in report.findings.iter().enumerate() {
        let _ = writeln!(
            out,
            "### Finding {}: {} [{}]\n\n{}\n\nEvidence: {}\n\nUncertainty: {}\n",
            index + 1,
            finding.kind.as_str(),
            finding.severity.as_str(),
            finding.text,
            finding.evidence.join(", "),
            finding.uncertainty
        );
    }
}

fn delivery_section(out: &mut String, report: &RunReport) {
    out.push_str("\n## Delivery\n\n");
    match &report.delivery {
        None => out.push_str("The model did not deliver a summary.\n"),
        Some(delivery) => {
            let _ = writeln!(out, "{}\n", delivery.summary);
            list(out, "Next steps", &delivery.next_steps);
            list(out, "Unresolved", &delivery.unresolved);
        }
    }
}

fn suggestions_section(out: &mut String, suggestions: &[Suggestion]) {
    if suggestions.is_empty() {
        return;
    }
    out.push_str("\n## Suggested experiments (not run)\n");
    for (index, suggestion) in suggestions.iter().enumerate() {
        let _ = writeln!(
            out,
            "\n{}. **{}**\n\n   Why: {}\n\n   Method: {}\n\n   Estimated cost: {}",
            index + 1,
            suggestion.question,
            suggestion.why,
            suggestion.method,
            suggestion.estimated_cost
        );
    }
}

fn list(out: &mut String, title: &str, items: &[String]) {
    let _ = writeln!(out, "\n{title}:");
    if items.is_empty() {
        out.push_str("- none\n");
        return;
    }
    for item in items {
        let _ = writeln!(out, "- {item}");
    }
}

fn limits_section(out: &mut String) {
    out.push_str(
        "\n## Limits of this record\n\n\
         - The sandbox is a complete copy with path containment, not an operating-system jail. A \
           command can still read or write elsewhere under the user's account and can use the \
           network.\n\
         - A timeout kills the direct child only; a grandchild may survive, and the outcome says \
           whether both output pipes reached EOF.\n\
         - The provider boundary in this build speaks plain HTTP to a local endpoint. No HTTPS or \
           vendor endpoint was exercised.\n\
         - No patch or improvement was applied. The plan's tasks were observations; follow-up work \
           is listed, not done.\n",
    );
}

fn record_section(out: &mut String, report: &RunReport) {
    let _ = writeln!(
        out,
        "\n## Record\n\n- Directory: `{}`\n- Journal: {} events, head `{}`\n- Sandbox copy digest: `{}`\n- Workspace: `workspace/`",
        shown(&report.root),
        report.journal_events,
        report.journal_head,
        report.sandbox_sha256
    );
}

fn shown(path: &std::path::Path) -> String {
    let text = path.display().to_string();
    text.strip_prefix(r"\\?\")
        .map_or(text.clone(), str::to_string)
}

fn operation_text(validated: Option<&ValidatedPlan>, task_id: &str) -> Option<String> {
    let validated = validated?;
    let task = validated
        .tasks
        .iter()
        .find(|task| task.task.id == task_id)?;
    Some(match &task.operation {
        crate::plan::Operation::Instrument {
            model,
            budget,
            archive,
        } => format!("run `{model}` --budget {budget} --archive `{archive}`"),
        crate::plan::Operation::Exec { argv, timeout_ms } => {
            format!("exec `{}` (timeout {timeout_ms} ms)", argv.join(" "))
        }
    })
}

/// The machine-readable summary, written beside the human report.
#[must_use]
pub fn machine_summary(report: &RunReport) -> Json {
    let tasks = report
        .results
        .iter()
        .map(|result| {
            Json::object(vec![
                ("id", Json::text(&result.id)),
                ("task_id", Json::text(&result.task_id)),
                ("tool", Json::text(&result.tool)),
                ("status", Json::text(&result.status)),
                (
                    "exit_code",
                    result.exit_code.map_or(Json::Null, |code| {
                        Json::count(u64::try_from(code).unwrap_or(0))
                    }),
                ),
                ("duration_ms", Json::count(result.duration_ms)),
                (
                    "artifacts",
                    Json::Arr(result.artifacts.iter().map(Artifact::to_json).collect()),
                ),
            ])
        })
        .collect();
    let findings = report
        .findings
        .iter()
        .map(crate::plan::Finding::to_json)
        .collect();
    let suggestions = report.suggestions.iter().map(Suggestion::to_json).collect();
    Json::object(vec![
        ("schema", Json::count(1)),
        ("id", Json::text(&report.id)),
        ("outcome", Json::text(report.outcome.as_str())),
        ("objective", Json::text(&report.objective)),
        ("provider", Json::text(&report.provider)),
        ("started", Json::text(&report.started)),
        ("finished", Json::text(&report.finished)),
        (
            "source",
            Json::object(vec![
                ("path", Json::text(report.source.display().to_string())),
                (
                    "git_head",
                    report
                        .inspection
                        .summary
                        .git_head
                        .as_ref()
                        .map_or(Json::Null, Json::text),
                ),
            ]),
        ),
        ("tasks", Json::Arr(tasks)),
        ("findings", Json::Arr(findings)),
        ("suggestions", Json::Arr(suggestions)),
        (
            "delivery",
            report
                .delivery
                .as_ref()
                .map_or(Json::Null, Delivery::to_json),
        ),
        (
            "failure",
            report.failure.as_ref().map_or(Json::Null, Json::text),
        ),
        (
            "journal",
            Json::object(vec![
                ("events", Json::count(report.journal_events)),
                ("head", Json::text(&report.journal_head)),
            ]),
        ),
        ("sandbox_sha256", Json::text(&report.sandbox_sha256)),
        ("workspace", Json::text("workspace")),
    ])
}
